    private Button btnSchedule, btnPayment;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_dashboard);
            View spinnerTattooDesign = findViewById(R.id.spinnerTattooDesign);

        btnSchedule = findViewById(R.id.btnSchedule);
        btnPayment = findViewById(R.id.btnPayment);

        btnSchedule.setOnClickListener(v ->
                Toast.makeText(this, "Schedule Appointment clicked!", Toast.LENGTH_SHORT).show());

        btnPayment.setOnClickListener(v ->
                Toast.makeText(this, "Proceed to Payment clicked!", Toast.LENGTH_SHORT).show());
    }
}

